import { test, expect } from '@playwright/test';

test.describe('Image Upload Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should display error for small image dimensions', async ({ page }) => {
    const filePath = 'path/to/small-image.jpg'; // Replace with the path to a small image
    await page.setInputFiles(getByLabel('Upload Image'), filePath);
    await page.click(getByRole('button', { name: 'Submit' }));

    const errorMessage = await page.getByText('Image dimensions are too small. Please upload a larger image.');
    await expect(errorMessage).toBeVisible();
  });

  test('should not display error for valid image dimensions', async ({ page }) => {
    const filePath = 'path/to/valid-image.jpg'; // Replace with the path to a valid image
    await page.setInputFiles(getByLabel('Upload Image'), filePath);
    await page.click(getByRole('button', { name: 'Submit' }));

    const errorMessage = await page.getByText('Image dimensions are too small. Please upload a larger image.');
    await expect(errorMessage).not.toBeVisible();
  });
});
